    new_min_c = (cols - 1) - max_c
    new_max_c = (cols - 1) - min_c

    # Copy the frame to new position
    for i in range(h):
        for j in range(w):
            orig_r = min_r + i
            orig_c = min_c + j
            new_r = new_min_r + i
            new_c = new_min_c + j

            # Copy only the border (frame), not interior
            if i == 0 or i == h - 1 or j == 0 or j == w - 1:
                if 0 <= new_r < rows and 0 <= new_c < cols:
